  "live widget": ["widget activo", "Live-Widget", "canlı bileşen"],
  "need a confirmed date before they can appear in the agenda.": ["necesitan una fecha confirmada antes de aparecer en la agenda.", "benötigen ein bestätigtes Datum, bevor sie in der Agenda erscheinen.", "ajandada görünmeden önce onaylanmış bir tarihe ihtiyaç duyar."],

  // Full-product locale audit: dashboard, CRM, account and channel configuration
  "Everyone your AI team has spoken to, and what is still open for them.": ["Todas las personas con las que ha hablado tu equipo de IA y lo que sigue pendiente.", "Alle Personen, mit denen Ihr KI-Team gesprochen hat, und was für sie noch offen ist.", "Yapay zekâ ekibinizin görüştüğü herkes ve onlar için hâlâ açık olan konular."],
  Export: ["Exportar", "Exportieren", "Dışa aktar"],
  "Export CSV": ["Exportar CSV", "CSV exportieren", "CSV dışa aktar"],
  "Add contact": ["Añadir contacto", "Kontakt hinzufügen", "Kişi ekle"],
  "Everyone on record": ["Todos los contactos registrados", "Alle gespeicherten Kontakte", "Kayıtlı herkes"],
  "Has a request still open": ["Tiene una solicitud aún abierta", "Hat noch eine offene Anfrage", "Hâlâ açık talebi var"],
  "Appointment still to come": ["Tiene una cita pendiente", "Hat einen bevorstehenden Termin", "Yaklaşan randevusu var"],
  "Next appointment": ["Próxima cita", "Nächster Termin", "Sonraki randevu"],
  "Select every contact on this page": ["Seleccionar todos los contactos de esta página", "Alle Kontakte auf dieser Seite auswählen", "Bu sayfadaki tüm kişileri seç"],
  "Open full profile": ["Abrir perfil completo", "Vollständiges Profil öffnen", "Tam profili aç"],
  Unknown: ["Desconocido", "Unbekannt", "Bilinmiyor"],
